def gen(rng):
    def rs(n, k):
        return ''.join(rng.choice('abc'[:k]) for _ in range(n))
    def make_match(s):
        out = []
        i = 0
        while i < len(s):
            r = rng.random()
            if r < 0.25:
                out.append('?')
                i += 1
            elif r < 0.45:
                j = rng.randint(i, len(s))
                out.append('*')
                i = j
            else:
                out.append(s[i])
                i += 1
        if rng.random() < 0.3:
            out.append('*')
        return ''.join(out) or '*'
    def mutate(p):
        i = rng.randrange(len(p))
        return p[:i] + rng.choice('ab?*') + p[i + 1:]
    def fmt(p, s):
        return p + '\n' + s
    tests = [fmt('*', 'a'), fmt('?', 'a'), fmt('a', 'b'), fmt('a', 'aa'), fmt('aa', 'a'), fmt('*a', 'ba'), fmt('a*', 'ab'),
             fmt('b*kg?ound', 'background'), fmt('*a*b', 'ba'), fmt('a?c*', 'abcdef'), fmt('**', 'abc'), fmt('?*?', 'ab'), fmt('?*?', 'a')]
    for _ in range(40):
        s = rs(rng.randint(1, 8), rng.choice([2, 3]))
        t = rng.random()
        if t < 0.4:
            p = make_match(s)
        elif t < 0.7:
            p = mutate(make_match(s))
        else:
            p = ''.join(rng.choice('ab?*') for _ in range(rng.randint(1, 8)))
        tests.append(fmt(p, s))
    s = rs(3990, 3)
    tests.append(fmt(make_match(s), s))
    tests.append(fmt('*' + 'a' * 1999 + 'b', 'a' * 4000))
    tests.append(fmt('*a' * 1000 + 'b', 'a' * 3999 + 'b'))
    tests.append(fmt('?' * 4000, rs(4000, 3)))
    tests.append(fmt('*' * 4000, rs(4000, 3)))
    s = rs(3990, 2)
    tests.append(fmt(mutate(make_match(s)), s))
    return tests
